package com.gptscape;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import javax.swing.Icon;
import javax.swing.JButton;

/** Botão compacto e redondo com ícone, no estilo dos chats modernos. */
final class ChatButton extends JButton
{
	enum Style
	{
		/** Só o ícone; círculo discreto ao passar o mouse. */
		GHOST,
		/** Círculo preenchido (botão de enviar/parar). */
		FILLED
	}

	private static final Color FILLED_ENABLED = new Color(226, 226, 226);
	private static final Color FILLED_DISABLED = new Color(62, 62, 62);

	private Style style;

	ChatButton(Icon icon, Icon disabledIcon, String tooltip, Style style, int size)
	{
		super(icon);
		this.style = style;
		setDisabledIcon(disabledIcon);
		setToolTipText(tooltip);
		setPreferredSize(new Dimension(size, size));
		setMinimumSize(new Dimension(size, size));
		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setOpaque(false);
		setRolloverEnabled(true);
	}

	void setAppearance(Icon icon, Icon disabledIcon, String tooltip)
	{
		setIcon(icon);
		setDisabledIcon(disabledIcon);
		setToolTipText(tooltip);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int d = Math.min(getWidth(), getHeight()) - 2;
			float x = (getWidth() - d) / 2f;
			float y = (getHeight() - d) / 2f;

			if (style == Style.FILLED)
			{
				g2.setColor(isEnabled() ? FILLED_ENABLED : FILLED_DISABLED);
				g2.fill(new Ellipse2D.Float(x, y, d, d));
			}
			else if (isEnabled() && (getModel().isRollover() || getModel().isPressed()))
			{
				g2.setColor(ChatTheme.HOVER);
				g2.fill(new Ellipse2D.Float(x, y, d, d));
			}

			Icon icon = isEnabled() || getDisabledIcon() == null ? getIcon() : getDisabledIcon();
			if (icon != null)
			{
				icon.paintIcon(this, g2, (getWidth() - icon.getIconWidth()) / 2, (getHeight() - icon.getIconHeight()) / 2);
			}
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.gptscape;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Salva a conversa atual em .runelite/plugin-data/gptscape/conversation.json (somente papel, texto e
 * horário; nunca a API key). Toda leitura/escrita acontece numa thread de I/O própria.
 */
@Slf4j
@Singleton
public class ChatHistoryStore
{
	private static final int MAX_SAVED_MESSAGES = 200;
	private static final Type LIST_TYPE = new TypeToken<List<ChatMessage>>()
	{
	}.getType();

	private final Gson gson;
	/** Definido em {@link #start(Filepath)}; null enquanto o diretório do plugin não está disponível. */
	private volatile Filepath file;
	private ExecutorService io;

	@Inject
	ChatHistoryStore(Gson gson)
	{
		this.gson = gson;
	}

	ChatHistoryStore(Gson gson, Filepath file)
	{
		this.gson = gson;
		this.file = file;
	}

	/** @param file arquivo da conversa, dentro do diretório do plugin; null desativa o histórico salvo */
	public synchronized void start(Filepath file)
	{
		this.file = file;
		start();
	}

	public synchronized void start()
	{
		if (io == null || io.isShutdown())
		{
			io = Executors.newSingleThreadExecutor(r ->
			{
				Thread t = new Thread(r, "gemini-chat-history");
				t.setDaemon(true);
				return t;
			});
		}
	}

	/** Termina as gravações pendentes e encerra a thread. */
	public synchronized void stop()
	{
		if (io == null)
		{
			return;
		}
		io.shutdown();
		try
		{
			if (!io.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.debug("Gemini chat history writes did not finish in time");
			}
		}
		catch (InterruptedException e)
		{
			log.debug("Interrupted while waiting for Gemini chat history writes", e);
		}
		io = null;
	}

	public synchronized CompletableFuture<List<ChatMessage>> load()
	{
		if (io == null)
		{
			return CompletableFuture.completedFuture(Collections.emptyList());
		}
		return CompletableFuture.supplyAsync(this::read, io);
	}

	public synchronized void save(List<ChatMessage> messages)
	{
		if (io == null)
		{
			return;
		}
		int from = Math.max(0, messages.size() - MAX_SAVED_MESSAGES);
		List<ChatMessage> copy = new ArrayList<>(messages.subList(from, messages.size()));
		io.execute(() -> write(copy));
	}

	public synchronized void clear()
	{
		if (io == null)
		{
			deleteFile();
			return;
		}
		io.execute(this::deleteFile);
	}

	List<ChatMessage> read()
	{
		Filepath file = this.file;
		if (file == null || !file.isFile())
		{
			return Collections.emptyList();
		}
		try (Reader reader = file.openBufferedReader())
		{
			List<ChatMessage> loaded = gson.fromJson(reader, LIST_TYPE);
			if (loaded == null)
			{
				return Collections.emptyList();
			}
			List<ChatMessage> valid = new ArrayList<>();
			for (ChatMessage m : loaded)
			{
				if (m != null && m.getRole() != null && m.getContent() != null && !m.getContent().trim().isEmpty())
				{
					valid.add(m);
				}
			}
			return valid;
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("Could not read saved Gemini chat history", e);
			return Collections.emptyList();
		}
	}

	void write(List<ChatMessage> messages)
	{
		Filepath file = this.file;
		if (file == null)
		{
			return;
		}
		if (messages.isEmpty())
		{
			deleteFile();
			return;
		}
		try
		{
			file.getParent().createDirectories();
			Filepath tmp = file.getParent().joinSegment(file.getFileName() + ".tmp");
			try (Writer writer = tmp.openBufferedWriter())
			{
				gson.toJson(messages, LIST_TYPE, writer);
			}
			try
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e)
		{
			log.warn("Could not save Gemini chat history", e);
		}
	}

	private void deleteFile()
	{
		Filepath file = this.file;
		if (file == null)
		{
			return;
		}
		try
		{
			file.deleteIfExists();
		}
		catch (IOException e)
		{
			log.warn("Could not delete saved Gemini chat history", e);
		}
	}
}

package com.gptscape;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.GeneralPath;
import java.awt.geom.Line2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BiConsumer;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import net.runelite.client.util.ImageUtil;

/** Ícones vetoriais desenhados em código (sem imagens externas ou downloads). */
final class ChatIcons
{
	private ChatIcons()
	{
	}

	/** Arquivo do robô (OSRS) incluído no plugin, usado como avatar do assistente. */
	private static final String ASSISTANT_IMAGE = "assistant.png";
	private static final Map<Integer, ImageIcon> ASSISTANT_CACHE = new ConcurrentHashMap<>();

	/** Avatar do assistente (robô do OSRS) no tamanho pedido, reduzido com suavização e guardado em cache. */
	static Icon assistant(int size)
	{
		return ASSISTANT_CACHE.computeIfAbsent(size, s -> new ImageIcon(assistantImage(s)));
	}

	private static BufferedImage assistantImage(int size)
	{
		BufferedImage source = ImageUtil.loadImageResource(ChatIcons.class, ASSISTANT_IMAGE);
		Image scaled = source.getScaledInstance(size, size, Image.SCALE_SMOOTH);
		BufferedImage result = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = result.createGraphics();
		g.drawImage(scaled, 0, 0, null);
		g.dispose();
		return result;
	}

	static Icon arrowUp(int size, Color color)
	{
		return new PaintedIcon(size, (g, s) ->
		{
			g.setColor(color);
			g.setStroke(new BasicStroke(s * 0.14f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			float c = s / 2f;
			g.draw(new Line2D.Float(c, s * 0.82f, c, s * 0.2f));
			GeneralPath head = new GeneralPath();
			head.moveTo(s * 0.24f, s * 0.46f);
			head.lineTo(c, s * 0.2f);
			head.lineTo(s * 0.76f, s * 0.46f);
			g.draw(head);
		});
	}

	static Icon stop(int size, Color color)
	{
		return new PaintedIcon(size, (g, s) ->
		{
			g.setColor(color);
			float inset = s * 0.26f;
			g.fill(new RoundRectangle2D.Float(inset, inset, s - 2 * inset, s - 2 * inset, s * 0.15f, s * 0.15f));
		});
	}

	static Icon plus(int size, Color color)
	{
		return new PaintedIcon(size, (g, s) ->
		{
			g.setColor(color);
			g.setStroke(new BasicStroke(s * 0.12f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			float c = s / 2f;
			g.draw(new Line2D.Float(c, s * 0.18f, c, s * 0.82f));
			g.draw(new Line2D.Float(s * 0.18f, c, s * 0.82f, c));
		});
	}

	/** Quadrado com lápis: "New chat". */
	static Icon newChat(int size, Color color)
	{
		return new PaintedIcon(size, (g, s) ->
		{
			g.setColor(color);
			g.setStroke(new BasicStroke(s * 0.09f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			GeneralPath box = new GeneralPath();
			box.moveTo(s * 0.5f, s * 0.14f);
			box.lineTo(s * 0.2f, s * 0.14f);
			box.quadTo(s * 0.1f, s * 0.14f, s * 0.1f, s * 0.24f);
			box.lineTo(s * 0.1f, s * 0.8f);
			box.quadTo(s * 0.1f, s * 0.9f, s * 0.2f, s * 0.9f);
			box.lineTo(s * 0.76f, s * 0.9f);
			box.quadTo(s * 0.86f, s * 0.9f, s * 0.86f, s * 0.8f);
			box.lineTo(s * 0.86f, s * 0.52f);
			g.draw(box);
			GeneralPath pencil = new GeneralPath();
			pencil.moveTo(s * 0.4f, s * 0.62f);
			pencil.lineTo(s * 0.42f, s * 0.48f);
			pencil.lineTo(s * 0.8f, s * 0.1f);
			pencil.lineTo(s * 0.92f, s * 0.22f);
			pencil.lineTo(s * 0.54f, s * 0.6f);
			pencil.closePath();
			g.draw(pencil);
		});
	}

	/** Três pontos: menu "More". */
	static Icon more(int size, Color color)
	{
		return new PaintedIcon(size, (g, s) ->
		{
			g.setColor(color);
			float d = s * 0.16f;
			float y = s / 2f - d / 2;
			for (float x : new float[]{s * 0.14f, s / 2f - d / 2, s * 0.86f - d})
			{
				g.fill(new Ellipse2D.Float(x, y, d, d));
			}
		});
	}

	/** Imagem do ícone para o botão da barra lateral do RuneLite. */
	static BufferedImage navigationImage()
	{
		return assistantImage(16);
	}

	private static final class PaintedIcon implements Icon
	{
		private final int size;
		private final BiConsumer<Graphics2D, Float> painter;

		PaintedIcon(int size, BiConsumer<Graphics2D, Float> painter)
		{
			this.size = size;
			this.painter = painter;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
				g2.translate(x, y);
				painter.accept(g2, (float) size);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override
		public int getIconWidth()
		{
			return size;
		}

		@Override
		public int getIconHeight()
		{
			return size;
		}
	}
}

package com.gptscape;

import lombok.Value;

/** Uma mensagem da conversa, no formato de papéis usado pela API do Gemini (user/model). */
@Value
public class ChatMessage
{
	public enum Role
	{
		USER,
		MODEL
	}

	Role role;
	String content;
	long timestamp;

	public static ChatMessage user(String content)
	{
		return new ChatMessage(Role.USER, content, System.currentTimeMillis());
	}

	public static ChatMessage model(String content)
	{
		return new ChatMessage(Role.MODEL, content, System.currentTimeMillis());
	}
}

package com.gptscape;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;

/** Cores e fontes do chat: experiência do Gemini com a paleta escura do RuneLite. */
final class ChatTheme
{
	static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
	static final Color SURFACE = ColorScheme.DARKER_GRAY_COLOR;
	static final Color USER_BUBBLE = new Color(58, 58, 58);
	static final Color BORDER = ColorScheme.MEDIUM_GRAY_COLOR;
	static final Color TEXT = new Color(226, 226, 226);
	static final Color MUTED = new Color(150, 150, 150);
	static final Color LINK = new Color(122, 176, 255);
	static final Color ERROR = new Color(236, 110, 110);
	static final Color CODE_BACKGROUND = new Color(24, 24, 24);
	static final Color CODE_HEADER = new Color(33, 33, 33);
	static final Color INLINE_CODE = new Color(232, 196, 140);
	static final Color HOVER = new Color(255, 255, 255, 24);
	static final Color ACCENT = ColorScheme.BRAND_ORANGE;

	/** Fonte lógica do Java: tem fallback para acentos, CJK e outros alfabetos (a fonte do RuneScape não tem). */
	static final Font BODY_FONT = new Font(Font.DIALOG, Font.PLAIN, 12);
	static final Font SMALL_FONT = new Font(Font.DIALOG, Font.PLAIN, 11);
	static final Font CODE_FONT = new Font(Font.MONOSPACED, Font.PLAIN, 11);

	private ChatTheme()
	{
	}

	/** Texto com quebra de linha automática, selecionável, sem aparência de campo de edição. */
	static JTextArea wrappingText(String text, Color color, Font font)
	{
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setOpaque(false);
		area.setBorder(BorderFactory.createEmptyBorder());
		area.setForeground(color);
		area.setFont(font);
		area.setCaretColor(color);
		area.setSelectionColor(new Color(80, 110, 160));
		return area;
	}

	/** Copia texto para a área de transferência do sistema. */
	static boolean copyToClipboard(String text)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
			return true;
		}
		catch (IllegalStateException e)
		{
			// Área de transferência ocupada por outro programa
			return false;
		}
	}

	/** Ação discreta em forma de link (ex.: "Copy", "Regenerate"). */
	static JLabel actionLink(String text, String tooltip, Runnable action)
	{
		return actionLink(text, tooltip, MUTED, action);
	}

	static JLabel actionLink(String text, String tooltip, Color color, Runnable action)
	{
		JLabel label = new JLabel(text);
		label.setFont(SMALL_FONT);
		label.setForeground(color);
		label.setToolTipText(tooltip);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				action.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setForeground(TEXT);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setForeground(color);
			}
		});
		return label;
	}
}

package com.gptscape;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.event.MouseWheelEvent;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.text.DefaultCaret;

/** Bloco de código: cabeçalho com a linguagem e "Copy code"; rolagem horizontal quando necessário. */
final class CodeBlockView extends JPanel
{
	private final JLabel language = new JLabel();
	private final JLabel copy;
	private final JTextArea code = new JTextArea();
	private final JScrollPane scroll;
	private final JPanel header = new JPanel(new BorderLayout());

	CodeBlockView()
	{
		super(new BorderLayout());
		setBackground(ChatTheme.CODE_BACKGROUND);
		setBorder(BorderFactory.createLineBorder(ChatTheme.BORDER));

		language.setFont(ChatTheme.SMALL_FONT);
		language.setForeground(ChatTheme.MUTED);
		copy = ChatTheme.actionLink("Copy code", "Copy this code to the clipboard", this::copyCode);
		header.setBackground(ChatTheme.CODE_HEADER);
		header.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 8));
		header.add(language, BorderLayout.WEST);
		header.add(copy, BorderLayout.EAST);

		code.setEditable(false);
		code.setLineWrap(false);
		code.setFont(ChatTheme.CODE_FONT);
		code.setForeground(ChatTheme.TEXT);
		code.setBackground(ChatTheme.CODE_BACKGROUND);
		code.setCaretColor(ChatTheme.TEXT);
		code.setMargin(new Insets(6, 8, 6, 8));
		((DefaultCaret) code.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);

		scroll = new JScrollPane(code, ScrollPaneConstants.VERTICAL_SCROLLBAR_NEVER,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_AS_NEEDED);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getViewport().setBackground(ChatTheme.CODE_BACKGROUND);
		// A roda do mouse rola o chat; Shift + roda rola o código na horizontal
		scroll.setWheelScrollingEnabled(false);
		scroll.addMouseWheelListener(this::forwardWheel);

		add(header, BorderLayout.NORTH);
		add(scroll, BorderLayout.CENTER);
	}

	void setCode(String lang, String text)
	{
		String label = lang == null || lang.isEmpty() ? "code" : lang;
		if (!label.equals(language.getText()))
		{
			language.setText(label);
		}
		if (!text.equals(code.getText()))
		{
			code.setText(text);
			revalidate();
		}
	}

	String getCode()
	{
		return code.getText();
	}

	private void copyCode()
	{
		if (ChatTheme.copyToClipboard(code.getText()))
		{
			copy.setText("Copied");
			Timer reset = new Timer(1500, e -> copy.setText("Copy code"));
			reset.setRepeats(false);
			reset.start();
		}
	}

	private void forwardWheel(MouseWheelEvent e)
	{
		if (e.isShiftDown())
		{
			JScrollBar bar = scroll.getHorizontalScrollBar();
			bar.setValue(bar.getValue() + e.getUnitsToScroll() * 12);
			return;
		}
		JScrollPane outer = (JScrollPane) SwingUtilities.getAncestorOfClass(JScrollPane.class, this);
		if (outer != null)
		{
			outer.dispatchEvent(SwingUtilities.convertMouseEvent(scroll, e, outer));
		}
	}

	@Override
	public Dimension getPreferredSize()
	{
		int width = getWidth() > 0 ? getWidth() : 200;
		Insets insets = getInsets();
		Dimension text = code.getPreferredSize();
		int available = width - insets.left - insets.right;
		int scrollbar = text.width > available ? scroll.getHorizontalScrollBar().getPreferredSize().height : 0;
		return new Dimension(width, insets.top + insets.bottom + header.getPreferredSize().height + text.height + scrollbar);
	}
}

package com.gptscape;

/**
 * Fornece informações do jogo que o usuário escolheu compartilhar com o Gemini.
 * Implementações devem ser somente leitura e nunca devem interagir com o jogo.
 */
public interface GameContextProvider
{
	/**
	 * Texto curto descrevendo o estado do jogador (ex.: níveis), ou string vazia se não houver nada disponível.
	 * Pode bloquear brevemente; nunca é chamado na Event Dispatch Thread.
	 */
	String describe();
}

package com.gptscape;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
