package com.gptscape;

import java.awt.Component;
import java.awt.FlowLayout;
import java.awt.Font;
import java.util.List;
import javax.swing.Box;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.Timer;
import net.runelite.client.ui.FontManager;

/**
 * Resposta do Gemini: ícone + nome, texto sem caixa ao redor, status animado ("Thinking...")
 * e ações discretas (Copy / Regenerate / Try again). Durante o streaming só esta view é atualizada.
 */
final class ModelMessageView extends JPanel
{
	interface Listener
	{
		void onRegenerate(ModelMessageView view);

		void onRetry(ModelMessageView view);
	}

	private final JPanel body = new JPanel(new StackLayout(8));
	private final JLabel status = new JLabel();
	private final JTextArea error = ChatTheme.wrappingText("", ChatTheme.ERROR, ChatTheme.BODY_FONT);
	private final JLabel note = new JLabel();
	private final JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
	private final JLabel copy;
	private final JLabel regenerate;
	private final JLabel retry;
	private final JLabel help;
	private final JTextArea hint = ChatTheme.wrappingText("", ChatTheme.MUTED, ChatTheme.BODY_FONT);
	private final Timer dots;
	private Runnable helpAction;

	private String markdown = "";
	private String statusText;
	private int dotCount;

	ModelMessageView(Listener listener)
	{
		super(new StackLayout(5));
		setOpaque(false);

		JLabel title = new JLabel("GPTScape", ChatIcons.assistant(18), JLabel.LEFT);
		title.setIconTextGap(6);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ChatTheme.TEXT);
		JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		header.setOpaque(false);
		header.add(title);

		body.setOpaque(false);

		status.setFont(ChatTheme.BODY_FONT.deriveFont(Font.ITALIC));
		status.setForeground(ChatTheme.MUTED);
		status.setVisible(false);
		dots = new Timer(450, e -> animateStatus());

		error.setVisible(false);

		note.setFont(ChatTheme.SMALL_FONT.deriveFont(Font.ITALIC));
		note.setForeground(ChatTheme.MUTED);

		hint.setVisible(false);

		copy = ChatTheme.actionLink("Copy", "Copy response", this::copyResponse);
		regenerate = ChatTheme.actionLink("Regenerate", "Regenerate response", () -> listener.onRegenerate(this));
		retry = ChatTheme.actionLink("Try again", "Send your last message again", () -> listener.onRetry(this));
		help = ChatTheme.actionLink("", null, ChatTheme.LINK, () ->
		{
			if (helpAction != null)
			{
				helpAction.run();
			}
		});
		help.setVisible(false);
		actions.setOpaque(false);
		actions.setVisible(false);

		add(header);
		add(body);
		add(status);
		add(error);
		add(hint);
		add(actions);
	}

	/** Mostra um status animado (null esconde). Ex.: "Thinking", "Searching: zulrah". */
	void showStatus(String text)
	{
		if (text == null)
		{
			dots.stop();
			status.setVisible(false);
			statusText = null;
			return;
		}
		if (!text.equals(statusText))
		{
			statusText = text;
			dotCount = 3;
			status.setText(text + "...");
		}
		status.setVisible(true);
		if (!dots.isRunning())
		{
			dots.start();
		}
	}

	private void animateStatus()
	{
		if (statusText != null)
		{
			dotCount = dotCount % 3 + 1;
			status.setText(statusText + "...".substring(0, dotCount));
		}
	}

	/** Atualiza o conteúdo reaproveitando os blocos já existentes (só o que mudou é redesenhado). */
	void setMarkdown(String text)
	{
		boolean grew = text.length() > markdown.length();
		markdown = text;
		List<MarkdownRenderer.Block> blocks = MarkdownRenderer.parseBlocks(text);

		for (int i = 0; i < blocks.size(); i++)
		{
			MarkdownRenderer.Block block = blocks.get(i);
			Component existing = i < body.getComponentCount() ? body.getComponent(i) : null;
			if (block instanceof MarkdownRenderer.CodeBlock)
			{
				MarkdownRenderer.CodeBlock cb = (MarkdownRenderer.CodeBlock) block;
				CodeBlockView view = existing instanceof CodeBlockView ? (CodeBlockView) existing : new CodeBlockView();
				view.setCode(cb.language, cb.code);
				place(view, existing, i);
			}
			else
			{
				MarkdownTextView view = existing instanceof MarkdownTextView ? (MarkdownTextView) existing : new MarkdownTextView();
				view.setMarkdown(((MarkdownRenderer.TextBlock) block).markdown);
				place(view, existing, i);
			}
		}
		while (body.getComponentCount() > blocks.size())
		{
			body.remove(body.getComponentCount() - 1);
		}
		if (grew)
		{
			showStatus(null);
		}
		body.revalidate();
	}

	private void place(Component view, Component existing, int index)
	{
		if (view != existing)
		{
			if (existing != null)
			{
				body.remove(index);
			}
			body.add(view, index);
		}
	}

	/** Resposta concluída (ou interrompida com texto parcial). */
	void finish(boolean canRegenerate, String noteText)
	{
		showStatus(null);
		error.setVisible(false);
		hint.setVisible(false);
		help.setVisible(false);
		copy.setVisible(!markdown.isEmpty());
		regenerate.setVisible(canRegenerate);
		retry.setVisible(false);
		note.setText(noteText == null ? "" : noteText);
		note.setVisible(noteText != null);
		layoutActions();
		revalidate();
	}

	/** Falha: mostra a mensagem amigável e, se fizer sentido, "Try again". */
	void showError(String message, boolean canRetry)
	{
		showError(message, canRetry, null, null, null);
	}

	/**
	 * Falha com explicação extra e uma ação de ajuda (ex.: cota gratuita esgotada → "Get unlimited messages").
	 */
	void showError(String message, boolean canRetry, String hintText, String helpText, Runnable onHelp)
	{
		showStatus(null);
		error.setText(message);
		error.setVisible(true);
		hint.setText(hintText == null ? "" : hintText);
		hint.setVisible(hintText != null);
		helpAction = onHelp;
		help.setText(helpText == null ? "" : helpText);
		help.setVisible(helpText != null && onHelp != null);
		copy.setVisible(!markdown.isEmpty());
		regenerate.setVisible(false);
		retry.setVisible(canRetry);
		note.setVisible(false);
		layoutActions();
		revalidate();
	}

	void setRegenerateVisible(boolean visible)
	{
		if (regenerate.isVisible() != visible)
		{
			regenerate.setVisible(visible);
			layoutActions();
		}
	}

	/** Monta a linha de ações só com os itens visíveis, sem espaços sobrando. */
	private void layoutActions()
	{
		actions.removeAll();
		for (JLabel item : new JLabel[]{copy, regenerate, retry, help, note})
		{
			if (item.isVisible())
			{
				if (actions.getComponentCount() > 0)
				{
					actions.add(Box.createHorizontalStrut(14));
				}
				actions.add(item);
			}
		}
		actions.setVisible(actions.getComponentCount() > 0);
		actions.revalidate();
		actions.repaint();
	}

	String getMarkdown()
	{
		return markdown;
	}

	/** Para a animação (view removida ou plugin desligado). */
	void dispose()
	{
		dots.stop();
	}

	private void copyResponse()
	{
		if (ChatTheme.copyToClipboard(markdown))
		{
			copy.setText("Copied");
			Timer reset = new Timer(1500, e -> copy.setText("Copy"));
			reset.setRepeats(false);
			reset.start();
		}
	}
}

package com.gptscape;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.client.callback.ClientThread;

/**
 * Lê níveis do jogador pela API pública do RuneLite (somente leitura), apenas quando o usuário ativa
 * "Share Game Stats". Não envia o nome do personagem.
 */
@Slf4j
@Singleton
public class RuneLiteGameContextProvider implements GameContextProvider
{
	private static final String ACCOUNT_TOOLS_HINT = "The player lets you read more about their own account with the "
		+ "account_* tools. Call them whenever an answer depends on the player's own account, instead of asking "
		+ "the player or guessing.";

	private final Client client;
	private final ClientThread clientThread;
	private final GptScapeConfig config;

	@Inject
	RuneLiteGameContextProvider(Client client, ClientThread clientThread, GptScapeConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
	}

	@Override
	public String describe()
	{
		boolean accountTools = config.shareAccountData() || config.shareBank();
		if ((!config.shareGameStats() && !accountTools) || client.getGameState() != GameState.LOGGED_IN)
		{
			return "";
		}

		String tools = accountTools ? ACCOUNT_TOOLS_HINT : "";
		if (!config.shareGameStats())
		{
			return tools;
		}

		// A API do cliente deve ser lida na thread do cliente
		CompletableFuture<String> snapshot = new CompletableFuture<>();
		clientThread.invoke(() ->
		{
			try
			{
				snapshot.complete(readStats());
			}
			catch (RuntimeException e)
			{
				snapshot.completeExceptionally(e);
			}
		});

		try
		{
			return snapshot.get(2, TimeUnit.SECONDS) + (tools.isEmpty() ? "" : "\n" + tools);
		}
		catch (Exception e)
		{
			log.debug("Could not read game stats for Gemini context", e);
			return tools;
		}
	}

	private String readStats()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return "";
		}

		StringBuilder sb = new StringBuilder()
			.append("Combat level: ").append(player.getCombatLevel()).append('\n')
			.append("Total level: ").append(client.getTotalLevel()).append('\n')
			.append("Skill levels: ");
		boolean first = true;
		for (Skill skill : Skill.values())
		{
			if ("OVERALL".equals(skill.name()))
			{
				continue;
			}
			sb.append(first ? "" : ", ").append(skill.getName()).append(' ').append(client.getRealSkillLevel(skill));
			first = false;
		}
		return sb.toString();
	}
}

package com.gptscape;

import java.util.function.Consumer;

/**
 * Parser de Server-Sent Events (text/event-stream) linha a linha.
 * Recebe linhas já separadas (o leitor cuida de dados divididos entre leituras TCP),
 * junta várias linhas "data:" de um mesmo evento e entrega o evento na linha em branco
 * ou no fim do stream.
 */
final class SseParser
{
	private final Consumer<String> onEvent;
	private final StringBuilder data = new StringBuilder();
	private boolean hasData;

	SseParser(Consumer<String> onEvent)
	{
		this.onEvent = onEvent;
	}

	void feedLine(String rawLine)
	{
		String line = rawLine.endsWith("\r") ? rawLine.substring(0, rawLine.length() - 1) : rawLine;
		if (line.isEmpty())
		{
			dispatch();
			return;
		}
		if (line.startsWith(":"))
		{
			return; // comentário / keep-alive
		}

		int colon = line.indexOf(':');
		String field = colon < 0 ? line : line.substring(0, colon);
		String value = colon < 0 ? "" : line.substring(colon + 1);
		if (value.startsWith(" "))
		{
			value = value.substring(1);
		}

		if ("data".equals(field))
		{
			if (hasData)
			{
				data.append('\n');
			}
			data.append(value);
			hasData = true;
		}
		// Campos "event", "id" e "retry" não são usados pela API do Gemini
	}

	/** Fim do stream: entrega um evento final que não terminou com linha em branco. */
	void finish()
	{
		dispatch();
	}

	private void dispatch()
	{
		if (!hasData)
		{
			return;
		}
		String event = data.toString();
		data.setLength(0);
		hasData = false;
		if (!event.isEmpty() && !"[DONE]".equals(event))
		{
			onEvent.accept(event);
		}
	}
}

package com.gptscape;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Empilha os filhos verticalmente com a largura total do container. A altura de cada filho é
 * calculada para essa largura, o que faz textos com quebra de linha se adaptarem à largura do sidebar.
 */
final class StackLayout implements LayoutManager
{
	private final int gap;

	StackLayout(int gap)
	{
		this.gap = gap;
	}

	@Override
	public Dimension preferredLayoutSize(Container parent)
	{
		synchronized (parent.getTreeLock())
		{
			Insets insets = parent.getInsets();
			int width = parent.getWidth() > 0 ? parent.getWidth() : PluginPanel.PANEL_WIDTH;
			int inner = Math.max(1, width - insets.left - insets.right);
			int height = insets.top + insets.bottom;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (c.isVisible())
				{
					height += heightFor(c, inner);
					visible++;
				}
			}
			height += gap * Math.max(0, visible - 1);
			return new Dimension(width, height);
		}
	}

	@Override
	public Dimension minimumLayoutSize(Container parent)
	{
		return new Dimension(0, preferredLayoutSize(parent).height);
	}

	@Override
	public void layoutContainer(Container parent)
	{
		synchronized (parent.getTreeLock())
		{
			Insets insets = parent.getInsets();
			int inner = Math.max(1, parent.getWidth() - insets.left - insets.right);
			int y = insets.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = heightFor(c, inner);
				c.setBounds(insets.left, y, inner, h);
				y += h + gap;
			}
		}
	}

	/** Altura preferida do componente quando ele tem a largura indicada. */
	static int heightFor(Component c, int width)
	{
		if (c.getWidth() != width)
		{
			// Componentes de texto só calculam a quebra de linha depois de saberem a largura
			c.setSize(width, c.getHeight() > 0 ? c.getHeight() : Short.MAX_VALUE);
		}
		return c.getPreferredSize().height;
	}

	@Override
	public void addLayoutComponent(String name, Component comp)
	{
		// O layout usa apenas a ordem dos filhos; não há restrições por componente
	}

	@Override
	public void removeLayoutComponent(Component comp)
	{
		// O layout usa apenas a ordem dos filhos; não há restrições por componente
	}
}

package com.gptscape;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Monta a system instruction enviada ao Gemini (nunca exibida ao usuário). */
final class SystemPrompt
{
	private SystemPrompt()
	{
	}

	static String build(LocalDate today, boolean webAccess, String customInstructions, String gameContext)
	{
		StringBuilder sb = new StringBuilder()
			.append("You are GPTScape, an AI assistant integrated into RuneLite, the Old School RuneScape client, "
				+ "powered by Google Gemini. If asked who you are, say you are GPTScape, powered by Google Gemini. "
				+ "If asked who created or made you, say GPTScape was created by the player whose in-game name is "
				+ "Hylan. ")
			.append("Help the user mainly with Old School RuneScape (OSRS) questions, but also with general questions. ")
			.append("Be clear, objective and useful. Format answers with Markdown when it helps readability "
				+ "(short paragraphs, lists, bold, code blocks). Do not use emojis.\n\n")

			.append("Language: respond naturally in the same language as the user's latest message, unless the user "
				+ "explicitly asks for another language. The RuneLite plugin interface is in English, but your "
				+ "responses must follow the user's language. If the user switches languages during the "
				+ "conversation, smoothly switch as well; an explicit request about language takes priority, then the "
				+ "language of the current message, then earlier context. Tool results may be in English; still reply "
				+ "in the user's language. Do not mention or explain this language-selection behavior unless asked.\n\n")

			.append("Keep official Old School RuneScape names untranslated in every language (for example RuneLite, "
				+ "Grand Exchange, Theatre of Blood, Tombs of Amascut, Chambers of Xeric, Zulrah, Vorkath, Inferno, "
				+ "Slayer, Prayer, Protect from Melee, item, monster, quest and skill names) unless the user asks "
				+ "for a translation.\n\n")

			.append("Accuracy: never invent game data such as stats, drop rates, requirements or prices. If you are not "
				+ "sure, or the answer depends on recent updates, say so. You only know about the user's game state "
				+ "when it is explicitly provided below; never pretend to see their client, inventory, location or "
				+ "account otherwise.\n\n")

			.append("Today's date is ")
			.append(today.format(DateTimeFormatter.ofPattern("EEEE, MMMM d, yyyy", Locale.ENGLISH)))
			.append(".\n");

		if (webAccess)
		{
			sb.append("\nYou have real-time internet access through these tools: web_search, osrs_news, ge_price and "
				+ "open_page. Use them before answering whenever the question involves current "
				+ "information (news, game updates, prices, events, dates) or details you are not certain about. "
				+ "For OSRS updates use osrs_news and open the most recent post; for item prices use ge_price. "
				+ "When you used tools, end the answer with a short list of sources as Markdown links.\n")
				.append("The RuneScape Wiki does not allow its content to be used with generative AI, so these tools "
					+ "cannot read it: never try to open or search runescape.wiki pages. You may still give the player "
					+ "a link to a wiki page so they can read it themselves.\n");
		}
		else
		{
			sb.append("\nYou do not have internet access in this chat. If a question needs current information, "
				+ "say that your information may be out of date.\n");
		}

		if (gameContext != null && !gameContext.trim().isEmpty())
		{
			sb.append("\nPlayer context, shared by the user through the RuneLite plugin:\n")
				.append(gameContext.trim())
				.append('\n');
		}

		if (customInstructions != null && !customInstructions.trim().isEmpty())
		{
			sb.append("\nAdditional instructions from the user:\n").append(customInstructions.trim()).append('\n');
		}
		return sb.toString();
	}
}

package com.gptscape;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.JTextArea;

/** Mensagem do usuário: balão arredondado e discreto, alinhado à direita. */
final class UserMessageView extends JPanel
{
	private static final int PAD_X = 10;
	private static final int PAD_Y = 7;
	private static final int ARC = 16;
	private static final double MAX_WIDTH_RATIO = 0.85;

	private final JTextArea text;

	UserMessageView(String content)
	{
		super(null);
		setOpaque(false);
		text = ChatTheme.wrappingText(content, ChatTheme.TEXT, ChatTheme.BODY_FONT);
		add(text);
	}

	private Rectangle bubble(int width)
	{
		int maxText = Math.max(40, (int) (width * MAX_WIDTH_RATIO) - PAD_X * 2);
		int textWidth = Math.min(maxText, naturalWidth());
		text.setSize(textWidth, Short.MAX_VALUE);
		int textHeight = text.getPreferredSize().height;
		int bubbleWidth = textWidth + PAD_X * 2;
		return new Rectangle(width - bubbleWidth, 0, bubbleWidth, textHeight + PAD_Y * 2);
	}

	/** Largura da linha mais longa, sem quebra. */
	private int naturalWidth()
	{
		FontMetrics fm = text.getFontMetrics(text.getFont());
		int max = 0;
		for (String line : text.getText().split("\n", -1))
		{
			max = Math.max(max, fm.stringWidth(line));
		}
		return max + 2;
	}

	@Override
	public Dimension getPreferredSize()
	{
		int width = getWidth() > 0 ? getWidth() : 200;
		return new Dimension(width, bubble(width).height);
	}

	@Override
	public void doLayout()
	{
		Rectangle r = bubble(getWidth());
		text.setBounds(r.x + PAD_X, r.y + PAD_Y, r.width - PAD_X * 2, r.height - PAD_Y * 2);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			Rectangle r = text.getBounds();
			g2.setColor(ChatTheme.USER_BUBBLE);
			g2.fill(new RoundRectangle2D.Float(r.x - PAD_X, r.y - PAD_Y, r.width + PAD_X * 2, r.height + PAD_Y * 2,
				ARC, ARC));
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.gptscape;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.InetAddress;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Ferramentas de internet gratuitas que o Gemini pode chamar (function calling).
 * A pesquisa do próprio Google não é liberada no plano gratuito, então o plugin faz as buscas.
 */
@Slf4j
@Singleton
public class WebTools
{
	private static final String BROWSER_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
		+ "(KHTML, like Gecko) Chrome/130.0 Safari/537.36";
	private static final String NEWS_URL = "https://secure.runescape.com/m=news/archive?oldschool=1";
	/**
	 * A política de IA generativa da RuneScape Wiki não permite usar o conteúdo dela com IA
	 * (https://meta.runescape.wiki/w/Meta:Generative_AI_policy): o plugin nunca lê nada desse domínio.
	 */
	private static final String WIKI_DOMAIN = "runescape.wiki";
	static final String WIKI_REFUSAL = "The RuneScape Wiki does not allow its content to be used with generative AI, "
		+ "so its pages cannot be read here. You may give the player the link to open themselves.";
	private static final int MAX_PRICE_RESULTS = 6;
	private static final int MAX_PAGE_CHARS = 12000;

	private static final Pattern NEWS_ARTICLE = Pattern.compile(
		"news-list-article__title-link' href='([^']+)'>([^<]+)</a>.*?"
			+ "news-list-article__category'>([^<]*)</span>.*?"
			+ "datetime='([^']+)'.*?"
			+ "news-list-article__summary'>(.*?)<a", Pattern.DOTALL);
	private static final Pattern DDG_RESULT = Pattern.compile(
		"<a rel=\"nofollow\" href=\"([^\"]+)\" class='result-link'>(.*?)</a>.*?"
			+ "class='result-snippet'>(.*?)</td>", Pattern.DOTALL);

	private final OkHttpClient httpClient;
	private final Gson gson;

	/** Preços do próprio RuneLite; null fora do cliente (testes e ferramentas de desenvolvimento). */
	private final ItemManager itemManager;

	WebTools(OkHttpClient httpClient, Gson gson)
	{
		this(httpClient, gson, null);
	}

	@Inject
	WebTools(OkHttpClient httpClient, Gson gson, ItemManager itemManager)
	{
		this.httpClient = httpClient.newBuilder()
			.connectTimeout(10, TimeUnit.SECONDS)
			.readTimeout(20, TimeUnit.SECONDS)
			.followRedirects(true)
			// Vale para toda requisição, inclusive redirecionamentos: nada é enviado à wiki
			.addNetworkInterceptor(chain ->
			{
				if (isWiki(chain.request().url().toString()))
				{
					throw new IOException(WIKI_REFUSAL);
				}
				return chain.proceed(chain.request());
			})
			.build();
		this.gson = gson;
		this.itemManager = itemManager;
	}

	/** Ferramentas no formato nativo da API do Gemini: {"functionDeclarations": [...]}. */
	JsonObject toolDeclarations()
	{
		JsonArray tools = new JsonArray();
		tools.add(tool("web_search",
			"Searches the internet (DuckDuckGo) and returns titles, links and snippets. Use it for any current "
				+ "information, news, prices, dates, events or anything you are not sure about.",
			"query", "Search terms. Prefer English for game-related topics."));
		tools.add(tool("osrs_news",
			"Lists the latest official Old School RuneScape news and updates (Jagex website), with date, "
				+ "category, summary and link. Use it for questions about updates, patch notes and events.",
			null, null));
		tools.add(tool("ge_price",
			"Current Grand Exchange price of an OSRS item, from RuneLite's own price data. Always use it for "
				+ "questions about an item's price, value or cost.",
			"item", "Item name in English (e.g. 'Twisted bow', 'Abyssal whip')."));
		tools.add(tool("open_page",
			"Opens a web page and returns its text. Use it to read a link found in a search or a full news post. "
				+ "It cannot open RuneScape Wiki pages.",
			"url", "Full address starting with https://"));

		JsonObject declarations = new JsonObject();
		declarations.add("functionDeclarations", tools);
		return declarations;
	}

	private static JsonObject tool(String name, String description, String param, String paramDescription)
	{
		JsonObject function = new JsonObject();
		function.addProperty("name", name);
		function.addProperty("description", description);

		if (param != null)
		{
			JsonObject p = new JsonObject();
			p.addProperty("type", "STRING");
			p.addProperty("description", paramDescription);
			JsonObject properties = new JsonObject();
			properties.add(param, p);
			JsonArray required = new JsonArray();
			required.add(param);

			JsonObject parameters = new JsonObject();
			parameters.addProperty("type", "OBJECT");
			parameters.add("properties", properties);
			parameters.add("required", required);
			function.add("parameters", parameters);
		}
		return function;
	}

	/** Texto curto para mostrar ao usuário enquanto a ferramenta roda. */
	static String describe(String name, JsonObject args)
	{
		switch (name)
		{
			case "web_search":
				return "Searching: " + arg(args, "query");
			case "osrs_news":
				return "Reading OSRS news";
			case "ge_price":
				return "Checking price: " + arg(args, "item");
			case "open_page":
				HttpUrl url = HttpUrl.parse(arg(args, "url"));
				return "Reading " + (url != null ? url.host() : "page");
			default:
				return "Searching";
		}
	}

	/** Executa a ferramenta (bloqueante) e devolve o resultado em texto para o modelo. */
	String execute(String name, JsonObject args)
	{
		try
		{
			switch (name)
			{
				case "web_search":
					return webSearch(arg(args, "query"));
				case "osrs_news":
					return osrsNews();
				case "ge_price":
					return gePrice(arg(args, "item"));
				case "open_page":
					return openPage(arg(args, "url"));
				default:
					return "Unknown tool: " + name;
			}
		}
		catch (Exception e)
		{
			log.debug("Falha na ferramenta {}", name, e);
			return "Error running " + name + ": " + e.getMessage();
		}
	}

	private String webSearch(String query) throws IOException
	{
		if (query.isEmpty())
		{
			return "Empty query.";
		}

		HttpUrl url = HttpUrl.parse("https://lite.duckduckgo.com/lite/").newBuilder()
			.addQueryParameter("q", query)
			.build();
		return searchResults(query, get(url.toString(), BROWSER_UA));
	}

	/** Extrai os resultados da página de busca, sem os anúncios e sem nada da wiki. */
	static String searchResults(String query, String html)
	{
		StringBuilder sb = new StringBuilder("Search results for \"" + query + "\":\n\n");
		Matcher m = DDG_RESULT.matcher(html);
		int count = 0;
		while (m.find() && count < 8)
		{
			String link = decodeDdgLink(m.group(1));
			if (link.contains("duckduckgo.com/y.js"))
			{
				continue; // anúncio
			}
			if (isWiki(link))
			{
				continue; // o trecho do resultado é conteúdo da wiki
			}
			count++;
			sb.append(count).append(". ").append(htmlToText(m.group(2))).append('\n')
				.append("   ").append(link).append('\n')
				.append("   ").append(htmlToText(m.group(3))).append("\n\n");
		}

		return count == 0 ? "No results found for \"" + query + "\"." : sb.toString();
	}

	private static String decodeDdgLink(String href)
	{
		String h = href.replace("&amp;", "&");
		int i = h.indexOf("uddg=");
		if (i >= 0)
		{
			String enc = h.substring(i + 5);
			int amp = enc.indexOf('&');
			if (amp >= 0)
			{
				enc = enc.substring(0, amp);
			}
			try
			{
				return URLDecoder.decode(enc, StandardCharsets.UTF_8.name());
			}
			catch (Exception ignored)
			{
			}
		}
		return h.startsWith("//") ? "https:" + h : h;
	}

	private String osrsNews() throws IOException
	{
		String html = get(NEWS_URL, BROWSER_UA);
		StringBuilder sb = new StringBuilder("Latest official Old School RuneScape news:\n\n");
		Matcher m = NEWS_ARTICLE.matcher(html);
		int count = 0;
		while (m.find() && count < 12)
		{
			count++;
			sb.append("- [").append(m.group(4)).append("] ").append(htmlToText(m.group(2)))
				.append(" (").append(htmlToText(m.group(3))).append(")\n")
				.append("  ").append(htmlToText(m.group(5))).append('\n')
				.append("  ").append(m.group(1)).append("\n\n");
		}

		if (count == 0)
		{
			return "Could not read the news. Page: " + NEWS_URL;
		}
		return sb.append("Use open_page with the link to read the full post.").toString();
	}

	/** Preço pelo ItemManager do RuneLite: não faz nenhuma requisição. */
	private String gePrice(String item)
	{
		if (item.isEmpty())
		{
			return "Empty item name.";
		}
		if (itemManager == null)
		{
			return "Item prices are only available inside RuneLite.";
		}

		String wanted = item.toLowerCase(Locale.ROOT);
		List<ItemPrice> matches = new ArrayList<>();
		for (ItemPrice price : itemManager.search(item))
		{
			if (price.getName().toLowerCase(Locale.ROOT).equals(wanted))
			{
				matches.add(0, price);
			}
			else
			{
				matches.add(price);
			}
		}
		if (matches.isEmpty())
		{
			return "Item \"" + item + "\" not found on the Grand Exchange. Check the English item name.";
		}

		StringBuilder sb = new StringBuilder("Grand Exchange prices (RuneLite price data):\n\n");
		for (ItemPrice price : matches.subList(0, Math.min(matches.size(), MAX_PRICE_RESULTS)))
		{
			sb.append("- ").append(price.getName()).append(": ")
				.append(String.format(Locale.US, "%,d", itemManager.getItemPrice(price.getId()))).append(" gp\n");
		}
		return sb.toString();
	}

	static boolean isWiki(String address)
	{
		HttpUrl url = HttpUrl.parse(address);
		if (url == null)
		{
			// Endereço que não dá para interpretar: na dúvida, trata como wiki se mencionar o domínio
			return address.toLowerCase(Locale.ROOT).contains(WIKI_DOMAIN);
		}
		return url.host().equals(WIKI_DOMAIN) || url.host().endsWith("." + WIKI_DOMAIN);
	}

	private String openPage(String rawUrl) throws IOException
	{
		HttpUrl url = HttpUrl.parse(rawUrl);
		if (url == null)
		{
			return "Invalid address: " + rawUrl;
		}
		if (isWiki(url.toString()))
		{
			return WIKI_REFUSAL;
		}
		if (isPrivateHost(url.host()))
		{
			return "Local addresses are not allowed.";
		}

		String body = get(url.toString(), BROWSER_UA);
		String text = body.trim().startsWith("<") ? htmlToText(body) : body;
		return "Content of " + url + ":\n\n" + truncate(text, MAX_PAGE_CHARS);
	}

	private static boolean isPrivateHost(String host)
	{
		try
		{
			InetAddress addr = InetAddress.getByName(host);
			return addr.isLoopbackAddress() || addr.isSiteLocalAddress() || addr.isLinkLocalAddress()
				|| addr.isAnyLocalAddress();
		}
		catch (Exception e)
		{
			return true;
		}
	}

	private String get(String url, String userAgent) throws IOException
	{
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", userAgent)
			.header("Accept-Language", "en-US,en;q=0.9")
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody body = response.body();
			if (!response.isSuccessful() || body == null)
			{
				throw new IOException("HTTP " + response.code());
			}
			return body.string();
		}
	}

	static String htmlToText(String html)
	{
		String text = html
			.replaceAll("(?is)<(script|style|noscript|svg|head)[^>]*>.*?</\\1>", " ")
			.replaceAll("(?is)<!--.*?-->", " ")
			.replaceAll("(?i)<br\\s*/?>|</(p|div|li|h[1-6]|tr|article|section)>", "\n")
			.replaceAll("<[^>]+>", " ")
			.replace("&nbsp;", " ")
			.replace("&amp;", "&")
			.replace("&quot;", "\"")
			.replace("&#39;", "'")
			.replace("&#x27;", "'")
			.replace("&lt;", "<")
			.replace("&gt;", ">")
			.replaceAll("[ \\t\\x0B\\f\\r]+", " ")
			.replaceAll(" *\n *", "\n")
			.replaceAll("\n{3,}", "\n\n");
		return text.trim();
	}

	private static String truncate(String s, int max)
	{
		return s.length() <= max ? s : s.substring(0, max) + "\n[... content truncated]";
	}

	private static String arg(JsonObject args, String key)
	{
		JsonElement e = args != null ? args.get(key) : null;
		return e == null || e.isJsonNull() ? "" : e.getAsString().trim();
	}
}

package com.gptscape;

import com.google.gson.Gson;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.List;
import net.runelite.client.util.Filepath;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class ChatHistoryStoreTest
{
	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void salvaECarregaComAcentosEEmoji() throws Exception
	{
		File file = new File(folder.getRoot(), "chat/conversation.json");
		ChatHistoryStore store = new ChatHistoryStore(new Gson(), filepath(file));
		store.write(Arrays.asList(ChatMessage.user("Como faço o Theatre of Blood? ção 🙂"), ChatMessage.model("**Sim**")));

		List<ChatMessage> loaded = store.read();
		assertEquals(2, loaded.size());
		assertEquals("Como faço o Theatre of Blood? ção 🙂", loaded.get(0).getContent());
		assertEquals(ChatMessage.Role.MODEL, loaded.get(1).getRole());

		String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
		assertFalse(json.toLowerCase().contains("apikey"));
	}

	@Test
	public void arquivoCorrompidoNaoQuebra() throws Exception
	{
		File file = folder.newFile("conversation.json");
		Files.write(file.toPath(), "{not json".getBytes(StandardCharsets.UTF_8));
		assertTrue(new ChatHistoryStore(new Gson(), filepath(file)).read().isEmpty());
	}

	@Test
	public void listaVaziaApagaArquivo() throws Exception
	{
		File file = folder.newFile("conversation.json");
		new ChatHistoryStore(new Gson(), filepath(file)).write(java.util.Collections.emptyList());
		assertFalse(file.exists());
	}

	@Test
	public void semDiretorioNaoQuebra()
	{
		ChatHistoryStore store = new ChatHistoryStore(new Gson());
		store.write(Arrays.asList(ChatMessage.user("oi")));
		assertTrue(store.read().isEmpty());
	}

	private Filepath filepath(File file)
	{
		return Filepath.Unchecked.getRooted(folder.getRoot().toPath()).join(folder.getRoot().toPath().relativize(file.toPath()).toString());
	}
}

package com.gptscape;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.lang.reflect.Proxy;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GameToolsTest
{
	private static GameTools tools(boolean account, boolean bank)
	{
		GptScapeConfig config = (GptScapeConfig) Proxy.newProxyInstance(GptScapeConfig.class.getClassLoader(),
			new Class<?>[]{GptScapeConfig.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "shareAccountData":
						return account;
					case "shareBank":
						return bank;
					default:
						return null;
				}
			});
		return new GameTools(null, null, null, config);
	}

	@Test
	public void offersNothingUnlessTheUserSharesIt()
	{
		assertFalse(tools(false, false).isEnabled());
		assertEquals(0, tools(false, false).declarations().size());
	}

	@Test
	public void bankIsASeparateOptIn()
	{
		JsonArray account = tools(true, false).declarations();
		assertEquals(6, account.size());
		for (int i = 0; i < account.size(); i++)
		{
			String name = account.get(i).getAsJsonObject().get("name").getAsString();
			assertTrue(name, tools(true, false).handles(name));
			assertFalse(name, "account_bank".equals(name));
		}

		JsonArray bank = tools(false, true).declarations();
		assertEquals(1, bank.size());
		JsonObject bankTool = bank.get(0).getAsJsonObject();
		assertEquals("account_bank", bankTool.get("name").getAsString());
		// A busca é opcional: sem "required"
		assertFalse(bankTool.getAsJsonObject("parameters").has("required"));
	}

	@Test
	public void refusesToolsTheUserTurnedOff()
	{
		String refused = "The player has not allowed sharing this information.";
		assertEquals(refused, tools(true, false).execute("account_bank", new JsonObject()));
		assertEquals(refused, tools(false, true).execute("account_quests", new JsonObject()));
	}
}

package com.gptscape;

import com.google.gson.Gson;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Testes de integração com a API real do Gemini. Só rodam com a variável de ambiente GEMINI_API_KEY.
 */
public class GeminiClientTest
{
	private String key;
	private GeminiClient client;

	@Before
	public void setUp()
	{
		key = System.getenv("GEMINI_API_KEY");
		assumeTrue("GEMINI_API_KEY not set", key != null && !key.isEmpty());
		OkHttpClient http = new OkHttpClient();
		Gson gson = new Gson();
		client = new GeminiClient(http, gson, new WebTools(http, gson));
		client.start();
	}

	@After
	public void tearDown()
	{
		if (client != null)
		{
			client.stop();
		}
	}

	private static final class Collector implements GeminiClient.StreamListener
	{
		final List<String> deltas = Collections.synchronizedList(new ArrayList<>());
		final List<String> statuses = Collections.synchronizedList(new ArrayList<>());
		final AtomicReference<String> text = new AtomicReference<>();
		final AtomicReference<GeminiException> error = new AtomicReference<>();
		final CountDownLatch done = new CountDownLatch(1);

		@Override
		public void onStatus(String status)
		{
			statuses.add(status);
			System.out.println("STATUS " + status);
		}

		@Override
		public void onText(String delta)
		{
			deltas.add(delta);
		}

		@Override
		public void onComplete(String fullText, String model)
		{
			System.out.println("[" + model + "] (" + deltas.size() + " chunks) " + fullText);
			text.set(fullText);
			done.countDown();
		}

		@Override
		public void onError(GeminiException e)
		{
			System.out.println("ERROR " + e.getKind() + ": " + e.getMessage());
			error.set(e);
			done.countDown();
		}
	}

	private GeminiRequest request(List<ChatMessage> history, boolean web)
	{
		return new GeminiRequest(key, System.getenv().getOrDefault("GEMINI_MODEL", GeminiClient.DEFAULT_MODEL),
			history, web, () -> SystemPrompt.build(LocalDate.now(), web, "", ""));
	}

	@Test
	public void streamingEmVariosPedacos() throws Exception
	{
		Collector c = new Collector();
		client.sendStreamingMessage(request(Collections.singletonList(
			ChatMessage.user("Conte de 1 a 30 por extenso, um número por linha.")), false), c);
		assertTrue(c.done.await(3, TimeUnit.MINUTES));
		assertNull(String.valueOf(c.error.get()), c.error.get());
		assertTrue("expected several chunks, got " + c.deltas.size(), c.deltas.size() > 1);
		assertEquals(c.text.get(), String.join("", c.deltas).trim());
	}

	@Test
	public void lembraDoContexto() throws Exception
	{
		Collector c = new Collector();
		client.sendStreamingMessage(request(Arrays.asList(
			ChatMessage.user("My Slayer level is 85. Just say OK."),
			ChatMessage.model("OK."),
			ChatMessage.user("What Slayer level did I tell you? Answer with only the number.")), false), c);
		assertTrue(c.done.await(3, TimeUnit.MINUTES));
		assertNull(String.valueOf(c.error.get()), c.error.get());
		assertTrue(c.text.get(), c.text.get().contains("85"));
	}

	@Test
	public void usaFerramentasDeInternet() throws Exception
	{
		Collector c = new Collector();
		client.sendStreamingMessage(request(Collections.singletonList(
			ChatMessage.user("Quanto custa um Twisted bow agora no GE?")), true), c);
		assertTrue(c.done.await(3, TimeUnit.MINUTES));
		assertNull(String.valueOf(c.error.get()), c.error.get());
		assertTrue(c.statuses.toString(), c.statuses.stream().anyMatch(s -> s.startsWith("Checking price")));
	}

	@Test
	public void cancelarInterrompeSemCallbacks() throws Exception
	{
		Collector c = new Collector();
		GeminiClient.Generation g = client.sendStreamingMessage(request(Collections.singletonList(
			ChatMessage.user("Write a 600-word story about a dragon.")), false), c);
		Thread.sleep(1500);
		g.cancel();
		assertTrue(g.isCancelled());
		// Depois do cancelamento nenhum onComplete/onError deve chegar
		assertFalse(c.done.await(5, TimeUnit.SECONDS));
	}

	@Test
	public void chaveInvalidaGeraErroAmigavel() throws Exception
	{
		Collector c = new Collector();
		client.sendStreamingMessage(new GeminiRequest("invalid-key", GeminiClient.DEFAULT_MODEL,
			Collections.singletonList(ChatMessage.user("hi")), false, () -> ""), c);
		assertTrue(c.done.await(1, TimeUnit.MINUTES));
		assertEquals(GeminiException.Kind.INVALID_KEY, c.error.get().getKind());
		assertEquals("Invalid Gemini API key. Check your key in the plugin settings.", c.error.get().getUserMessage());
	}
}

package com.gptscape;

import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GeminiConversationTest
{
	@Test
	public void mantemContextoDaConversa()
	{
		GeminiConversation c = new GeminiConversation();
		c.add(ChatMessage.user("My Slayer level is 85."));
		c.add(ChatMessage.model("Nice!"));
		c.add(ChatMessage.user("Which Slayer monster do you recommend for me?"));

		List<ChatMessage> window = c.contextWindow(30);
		assertEquals(3, window.size());
		assertEquals("My Slayer level is 85.", window.get(0).getContent());
		assertEquals(ChatMessage.Role.USER, window.get(2).getRole());
	}

	@Test
	public void limitaQuantidadeEComecaComUsuario()
	{
		List<ChatMessage> all = Arrays.asList(
			ChatMessage.user("u1"), ChatMessage.model("m1"),
			ChatMessage.user("u2"), ChatMessage.model("m2"),
			ChatMessage.user("u3"));

		List<ChatMessage> window = GeminiConversation.contextWindow(all, 4, 10_000);
		// As 4 mais recentes seriam m1,u2,m2,u3; a janela não pode começar com "model"
		assertEquals(3, window.size());
		assertEquals("u2", window.get(0).getContent());
	}

	@Test
	public void limitaTamanhoMasSempreIncluiAUltima()
	{
		String huge = new String(new char[500]).replace('\0', 'x');
